// TestDeliverWebhookHonorsConfiguredTimeout guards against a regression to
// the old hardcoded `client := &http.Client{Timeout: 30 * time.Second}`,
// which ignored the user's --timeout flag entirely. A slow server plus a
// short configured timeout must fail fast (well under 30s), proving the
// timeout parameter -- not a fixed constant -- governs the request.
func TestDeliverWebhookHonorsConfiguredTimeout(t *testing.T) {
	t.Parallel()

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(500 * time.Millisecond)
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(server.Close)

	start := time.Now()
	err := deliverWebhook(server.URL, []byte(`{}`), false, 20*time.Millisecond)
	elapsed := time.Since(start)

	if err == nil {
		t.Fatal("expected a timeout error from deliverWebhook, got nil")
	}
	if elapsed > 300*time.Millisecond {
		t.Fatalf("deliverWebhook took %v; want it bounded by the 20ms configured timeout, not a hardcoded 30s default", elapsed)
	}
}

func TestDeliverWebhookSucceedsWithinTimeout(t *testing.T) {
	t.Parallel()

	var gotBody string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		buf := make([]byte, 2)
		n, _ := r.Body.Read(buf)
		gotBody = string(buf[:n])
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(server.Close)

	if err := deliverWebhook(server.URL, []byte(`{}`), false, time.Second); err != nil {
		t.Fatalf("deliverWebhook returned error: %v", err)
	}
	if gotBody != "{}" {
		t.Fatalf("server received body %q, want {}", gotBody)
	}
}
